// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const items = $input.all();

return items.map(item => {
  const lead = item.json;

  // ---------------------------------
  // BUDGET SCORE — max 25 points
  // ---------------------------------
  const budgetScores = {
  "Under $2,500": 8,
  "$2,500–$5,000": 15,
  "$5,000–$10,000": 20,
  "$10,000–$25,000": 25,
  "$25,000+": 25,
  "Not sure yet": 10
};

  // ---------------------------------
  // TIMELINE SCORE — max 20 points
  // ---------------------------------
  const timelineScores = {
    "As soon as possible": 20,
    "Within 30 days": 20,
    "1-3 months": 15,
    "3-6 months": 10,
    "6+ months": 5,
    "Just exploring": 3
  };

  // ---------------------------------
  // PROJECT READINESS — max 10 points
  // ---------------------------------
  const projectScores = {
    "Yes": 10,
    "Not sure yet": 5,
    "No": 2
  };

  // Calculate individual scores
  const budgetScore =
    budgetScores[lead.budget_range] ?? 0;

  const timelineScore =
    timelineScores[lead.timeline] ?? 0;

  const projectReadinessScore =
    projectScores[lead.considering_project] ?? 0;

  // Objective business-rule subtotal
  const businessRulesScore =
    budgetScore +
    timelineScore +
    projectReadinessScore;

  // Return original lead data + qualification data
  return {
    json: {
      ...lead,

      qualification: {
        budget_score: budgetScore,
        timeline_score: timelineScore,
        project_readiness_score: projectReadinessScore,
        business_rules_score: businessRulesScore,
        business_rules_max: 55
      }
    }
  };
});

