// Final Lead Qualification
// Combines deterministic business-rule scoring with AI qualitative analysis

const business = $("Qualification: Business Rules").first().json;
const aiResponse = $("Qualification: AI Analysis").first().json;

// OpenAI structured output is nested here
const ai = aiResponse.output[0].content[0].text;

// -------------------------
// VALIDATE AI SCORES
// -------------------------

const serviceFitScore = Number(ai.service_fit_score);
const problemClarityScore = Number(ai.problem_clarity_score);

if (
  !Number.isFinite(serviceFitScore) ||
  serviceFitScore < 0 ||
  serviceFitScore > 30
) {
  throw new Error("Invalid service_fit_score returned by AI");
}

if (
  !Number.isFinite(problemClarityScore) ||
  problemClarityScore < 0 ||
  problemClarityScore > 15
) {
  throw new Error("Invalid problem_clarity_score returned by AI");
}

// -------------------------
// FINAL SCORE
// -------------------------

const businessRulesScore = Number(
  business.qualification.business_rules_score
);

const aiScore = serviceFitScore + problemClarityScore;

const qualificationScore =
  businessRulesScore + aiScore;

// -------------------------
// QUALIFICATION STATUS
// -------------------------

let qualificationStatus;
let routingPriority;

if (qualificationScore >= 80) {
  qualificationStatus = "Highly Qualified";
  routingPriority = "High";
} else if (qualificationScore >= 60) {
  qualificationStatus = "Qualified";
  routingPriority = "Standard";
} else if (qualificationScore >= 40) {
  qualificationStatus = "Needs Review";
  routingPriority = "Review";
} else {
  qualificationStatus = "Not Qualified";
  routingPriority = "Low";
}

// -------------------------
// RETURN ENRICHED LEAD
// -------------------------

return [
  {
    json: {
      ...business,

      qualification: {
        ...business.qualification,

        service_fit_score: serviceFitScore,
        problem_clarity_score: problemClarityScore,
        ai_score: aiScore,

        qualification_score: qualificationScore,
        qualification_status: qualificationStatus,
        routing_priority: routingPriority
      },

      ai_analysis: {
        primary_need: ai.primary_need,
        problem_categories: ai.problem_categories,
        recommended_service: ai.recommended_service,
        lead_summary: ai.lead_summary,
        client_facing_summary: ai.client_facing_summary,
        suggested_solution: ai.suggested_solution,
        discovery_focus: ai.discovery_focus
      }
    }
  }
];
